fn get_element_check_property(arr: Vec<u64>, i: usize) -> u64 {
    // Ensure the index is within the strictly between 0 and arr.len() bounds.
    assert!(i > 0 && i < arr.len(), "Index out of valid range");

    let value = arr[i];

    // Optionally check the global property holds at this index.
    // (arr[k] == k + 2 for all valid k)
    debug_assert_eq!(
        value,
        i as u64 + 2,
        "Array property violated at index {}: found {}, expected {}",
        i,
        value,
        i as u64 + 2
    );

    value
}

